-- 597: SURREAL DREAMS (SCENARIO_LOCATION_SCOPE.md) — four imagined-world cards in the new Surreal Dreams tile,
-- built from the surreal nightly_seeds (Kevin 2026-09-30: "i hate to waste all those seeds we paid to create ...
-- only keep good seeds").
--
-- The 14 keep/mine categories of the audit (3,010 templates) were rewritten by Sonnet into 4-10 word backdrops (no
-- people, no action, no time-of-day or weather; 1,453 kept), then strictly re-graded S/A/B: only the S grade goes in
-- (plus 14 hand-checked A-grade spots that give Land of Giants enough non-wide spots for a cast). Eligibility follows
-- the playbook's two rules: character_eligible = non-wide, pure_scene_eligible = non-intimate.
--
-- The recipes (6 phrase arrays + fusions) were generated by generate-full-location-card.js under a descriptive name
-- that states each world's concept, then renamed here to their keys. biome fantasy_imagined; biome_config (axes +
-- WARDROBE + imagined=true) comes from gen-location-biome.js / gen-location-wardrobe.js after this. admin_only until
-- QA sign-off; picker_category surreal_dreams is one no released app lists. Re-runnable.

UPDATE public.location_cards SET name = 'land of giants' WHERE name ILIKE 'Land of Giants, a surreal dream world%'
  AND NOT EXISTS (SELECT 1 FROM public.location_cards WHERE name = 'land of giants');
UPDATE public.location_cards SET display_name = 'Land of Giants', picker_category = 'surreal_dreams', picker_tile = 'surreal_dreams',
  picker_sort_order = 10, biome = 'fantasy_imagined', is_approved = true, admin_only = true, content_kind = 'place'
WHERE name = 'land of giants';

ON CONFLICT (location_key, spot_text) DO NOTHING;

UPDATE public.location_cards SET name = 'gravity-free realm' WHERE name ILIKE 'Gravity''s Off, a surreal dream world%'
  AND NOT EXISTS (SELECT 1 FROM public.location_cards WHERE name = 'gravity-free realm');
UPDATE public.location_cards SET display_name = 'Gravity''s Off', picker_category = 'surreal_dreams', picker_tile = 'surreal_dreams',
  picker_sort_order = 20, biome = 'fantasy_imagined', is_approved = true, admin_only = true, content_kind = 'place'
WHERE name = 'gravity-free realm';

ON CONFLICT (location_key, spot_text) DO NOTHING;

UPDATE public.location_cards SET name = 'luminous realm' WHERE name ILIKE 'Glowing Elements, a surreal dream world%'
  AND NOT EXISTS (SELECT 1 FROM public.location_cards WHERE name = 'luminous realm');
UPDATE public.location_cards SET display_name = 'Glowing Elements', picker_category = 'surreal_dreams', picker_tile = 'surreal_dreams',
  picker_sort_order = 30, biome = 'fantasy_imagined', is_approved = true, admin_only = true, content_kind = 'place'
WHERE name = 'luminous realm';

ON CONFLICT (location_key, spot_text) DO NOTHING;

UPDATE public.location_cards SET name = 'impossible wonderland' WHERE name ILIKE 'Impossible Whimsy, a surreal dream world%'
  AND NOT EXISTS (SELECT 1 FROM public.location_cards WHERE name = 'impossible wonderland');
UPDATE public.location_cards SET display_name = 'Impossible Whimsy', picker_category = 'surreal_dreams', picker_tile = 'surreal_dreams',
  picker_sort_order = 40, biome = 'fantasy_imagined', is_approved = true, admin_only = true, content_kind = 'place'
WHERE name = 'impossible wonderland';

ON CONFLICT (location_key, spot_text) DO NOTHING;

-- The shared "surreal / absurd" scenario rows the tagging found no place for belong to Impossible Whimsy.
UPDATE public.dual_scenarios SET location_keys = array_append(coalesce(location_keys, '{}'), 'impossible wonderland')
WHERE proposed_location = 'surreal_absurd' AND pool <> 'holiday' AND NOT ('impossible wonderland' = ANY(coalesce(location_keys, '{}')));
UPDATE public.single_scenarios SET location_keys = array_append(coalesce(location_keys, '{}'), 'impossible wonderland')
WHERE proposed_location = 'surreal_absurd' AND pool <> 'holiday' AND NOT ('impossible wonderland' = ANY(coalesce(location_keys, '{}')));
